//! Requirement matching that understands Chinese writing variants instead of exact strings.
//!
//! Both the requirement and the narration are reduced to a *canonical* form before comparison:
//! 1. `narration::norm` — punctuation, spaces and case removed (ASCII and full-width);
//! 2. full-width letters / digits → half-width;
//! 3. Traditional → Simplified characters (OpenCC t2s table, `t2s_chars.txt`, generated by `gen_t2s.py`);
//! 4. Taiwan ↔ Mainland technical vocabulary unified (相容→兼容、使用者介面→用户界面、位元→位、軟體→软件…).
//!
//! A match then says *how* it matched (exact / 繁簡轉換 / 兩岸用語 / 同義詞) so the report can explain it, and a
//! requirement that is only partly present is a **warning**, not a failure. Only text that is really missing fails.

use once_cell::sync::Lazy;
use std::collections::HashMap;

static T2S: Lazy<HashMap<char, char>> = Lazy::new(|| {
    include_str!("t2s_chars.txt")
        .lines()
        .filter_map(|l| {
            let mut it = l.chars();
            Some((it.next()?, it.next()?))
        })
        .collect()
});

/// Characters OpenCC maps that are also correct Simplified in common words (乾坤, 瞭望, 藉口 …): never counted as
/// "Traditional characters in a Simplified script".
const AMBIGUOUS: &str = "乾瞭藉夥甚麼於";

/// Taiwan term → Mainland term (written in Traditional; converted with t2s at start-up). Longest first is applied.
const TERMS: &[(&str, &str)] = &[
    ("圖形使用者介面", "圖形用戶界面"), ("使用者介面", "用戶界面"), ("使用者", "用戶"), ("介面", "界面"), ("相容", "兼容"),
    ("位元組", "字節"), ("位元", "位"), ("軟體", "軟件"), ("硬體", "硬件"), ("韌體", "固件"), ("程式碼", "代碼"), ("程式", "程序"),
    ("記憶體", "內存"), ("硬碟", "硬盤"), ("光碟", "光盤"), ("磁碟", "磁盤"), ("軟碟", "軟盤"), ("隨身碟", "U盤"),
    ("網路", "網絡"), ("網際網路", "互聯網"), ("螢幕", "屏幕"), ("滑鼠", "鼠標"), ("印表機", "打印機"), ("晶片", "芯片"),
    ("處理器", "處理器"), ("作業系統", "操作系統"), ("檔案", "文件"), ("資料夾", "文件夾"), ("資料", "數據"), ("數位", "數字"),
    ("影片", "視頻"), ("視訊", "視頻"), ("伺服器", "服務器"), ("解析度", "分辨率"), ("演算法", "算法"), ("寬頻", "寬帶"),
    ("筆電", "筆記本電腦"), ("筆記型電腦", "筆記本電腦"), ("桌上型電腦", "台式電腦"), ("個人電腦", "個人電腦"), ("主機板", "主板"),
    ("顯示卡", "顯卡"), ("快取", "緩存"), ("執行緒", "線程"), ("物件", "對象"), ("變數", "變量"), ("函式", "函數"), ("列印", "打印"),
    ("登入", "登錄"), ("連結", "鏈接"), ("支援", "支持"), ("預設", "默認"), ("資訊", "信息"), ("訊號", "信號"), ("類比", "模擬"),
    ("運算", "運算"), ("向量", "矢量"), ("像素", "像素"), ("硬碟機", "硬盤驅動器"), ("輝達", "英偉達"), ("英特爾", "英特爾"),
];

/// Groups of names for the same thing (canonical forms are computed at start-up). A requirement matched only through
/// another member of its group passes, and the report says which wording was used.
const SYNONYMS: &[&[&str]] = &[
    &["圖形使用者介面", "圖形介面", "GUI", "圖形化介面", "圖形化使用者介面"],
    &["個人電腦", "個人計算機", "PC"],
    &["IBM相容電腦", "IBM相容機", "IBM PC相容機", "IBM PC相容電腦", "相容機"],
    &["微處理器", "CPU晶片", "微處理機"],
    &["作業系統", "OS"],
    &["人工智慧", "人工智能", "AI"],
    &["大型電腦", "大型主機", "主機型電腦"],
];

static TERMS_CANON: Lazy<Vec<(String, String)>> = Lazy::new(|| {
    let mut v: Vec<(String, String)> = TERMS.iter().map(|(a, b)| (t2s(&crate::narration::norm(a)), t2s(&crate::narration::norm(b)))).filter(|(a, b)| a != b).collect();
    v.sort_by_key(|(a, _)| std::cmp::Reverse(a.chars().count()));
    v
});

static SYN_CANON: Lazy<Vec<Vec<String>>> = Lazy::new(|| SYNONYMS.iter().map(|g| g.iter().map(|s| canon(s)).collect()).collect());

pub fn t2s(s: &str) -> String {
    s.chars().map(|c| *T2S.get(&c).unwrap_or(&c)).collect()
}

fn halfwidth(s: &str) -> String {
    s.chars()
        .map(|c| match c as u32 {
            0xFF01..=0xFF5E => char::from_u32(c as u32 - 0xFEE0).unwrap_or(c),
            _ => c,
        })
        .collect()
}

/// Canonical form: normalized, half-width, Simplified, Mainland vocabulary.
pub fn canon(s: &str) -> String {
    let mut x = t2s(&crate::narration::norm(&halfwidth(s)));
    for (a, b) in TERMS_CANON.iter() {
        if x.contains(a.as_str()) {
            x = x.replace(a.as_str(), b);
        }
    }
    x
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum How {
    Exact,
    Script,
    Regional,
    Synonym,
}

impl How {
    pub fn label(self) -> &'static str {
        match self {
            How::Exact => "完全相符",
            How::Script => "繁簡轉換後相符",
            How::Regional => "兩岸用語轉換後相符",
            How::Synonym => "同義詞",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Found {
    /// present; `used` is the wording found in the text (for the report)
    Yes { how: How, used: String },
    /// only partly present (share of the requirement's characters found as one run, 0..1)
    Partial { score: f64, used: String },
    No,
}

/// Longest common substring (chars) between `a` and `b`.
fn lcs(a: &[char], b: &[char]) -> (usize, usize) {
    let mut best = (0, 0);
    let mut prev = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        let mut cur = vec![0usize; b.len() + 1];
        for j in 1..=b.len() {
            if a[i - 1] == b[j - 1] {
                cur[j] = prev[j - 1] + 1;
                if cur[j] > best.0 {
                    best = (cur[j], j);
                }
            }
        }
        prev = cur;
    }
    best
}

/// Is requirement `needle` present in `hay` (any length text)?
pub fn find(needle: &str, hay: &str) -> Found {
    let (n_norm, h_norm) = (crate::narration::norm(needle), crate::narration::norm(hay));
    if n_norm.is_empty() {
        return Found::Yes { how: How::Exact, used: String::new() };
    }
    if h_norm.contains(&n_norm) {
        return Found::Yes { how: How::Exact, used: needle.to_string() };
    }
    let (n_s, h_s) = (t2s(&n_norm), t2s(&h_norm));
    if h_s.contains(&n_s) {
        return Found::Yes { how: How::Script, used: n_s };
    }
    let (n_c, h_c) = (canon(needle), canon(hay));
    if h_c.contains(&n_c) {
        return Found::Yes { how: How::Regional, used: n_c };
    }
    if let Some(g) = SYN_CANON.iter().find(|g| g.contains(&n_c)) {
        if let Some(alt) = g.iter().filter(|x| **x != n_c && x.chars().count() >= 2).find(|x| h_c.contains(x.as_str())) {
            return Found::Yes { how: How::Synonym, used: alt.clone() };
        }
    }
    let (nc, hc): (Vec<char>, Vec<char>) = (n_c.chars().collect(), h_c.chars().collect());
    let (len, end) = lcs(&nc, &hc);
    let score = len as f64 / nc.len().max(1) as f64;
    if nc.len() >= 3 && score >= 0.6 {
        return Found::Partial { score, used: hc[end - len..end].iter().collect() };
    }
    Found::No
}

/// Two titles are the same requirement (whole-string comparison on the canonical form; containment allowed).
pub fn same_title(want: &str, got: &str) -> Option<How> {
    let (a, b) = (crate::narration::norm(want), crate::narration::norm(got));
    let close = |x: &str, y: &str| !y.is_empty() && (x == y || y.contains(x) || x.contains(y));
    if close(&a, &b) {
        return Some(How::Exact);
    }
    if close(&t2s(&a), &t2s(&b)) {
        return Some(How::Script);
    }
    if close(&canon(want), &canon(got)) {
        return Some(How::Regional);
    }
    None
}

/// Similarity 0..1 of two titles (for "close but different" warnings).
pub fn title_similarity(want: &str, got: &str) -> f64 {
    let (a, b): (Vec<char>, Vec<char>) = (canon(want).chars().collect(), canon(got).chars().collect());
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    lcs(&a, &b).0 as f64 / a.len().max(b.len()) as f64
}

/// Traditional-only characters in a text that should be Simplified (ambiguous characters ignored).
pub fn traditional_chars(s: &str) -> Vec<char> {
    let mut v: Vec<char> = s.chars().filter(|c| T2S.contains_key(c) && !AMBIGUOUS.contains(*c)).collect();
    v.sort();
    v.dedup();
    v
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ep07_false_negatives_now_match() {
        // the three keywords and titles that failed EP07 three times (zh-CN script, requirements written in zh-TW)
        let nar = "八十年代被称为个人电脑革命的十年。很快，IBM兼容电脑遍地开花。苹果把图形用户界面带进家庭。";
        assert_eq!(find("個人電腦革命", nar), Found::Yes { how: How::Script, used: "个人电脑革命".into() });
        assert!(matches!(find("IBM相容電腦", nar), Found::Yes { how: How::Regional, .. }));
        assert!(matches!(find("圖形使用者介面", nar), Found::Yes { how: How::Regional, .. }));
        assert_eq!(same_title("序章：個人電腦革命之前", "序章：个人电脑革命之前"), Some(How::Script));
        assert_eq!(same_title("1985：Windows誕生與32位元時代", "1985：Windows诞生与32位时代"), Some(How::Regional));
        assert_eq!(same_title("1983～1984：Apple與圖形介面革命", "1983～1984：Apple与图形界面革命"), Some(How::Regional));
        assert_eq!(same_title("1986～1987：IBM相容電腦的崛起", "1986～1987：IBM兼容电脑的崛起"), Some(How::Regional));
    }

    #[test]
    fn synonyms_partial_and_real_misses() {
        assert!(matches!(find("圖形使用者介面", "麦金塔让 GUI 走进大众"), Found::Yes { how: How::Synonym, .. }));
        assert!(matches!(find("IBM相容電腦", "康柏推出了第一台兼容机"), Found::Yes { how: How::Synonym, .. }));
        // case, full-width, spacing and punctuation never matter
        assert!(matches!(find("Intel 80386", "英特尔推出ｉｎｔｅｌ８０３８６。"), Found::Yes { .. }));
        // only partly present → partial (warning), not a pass and not a silent failure
        assert!(matches!(find("個人電腦革命", "那是个人电脑的十年"), Found::Partial { .. }));
        // really missing → No
        assert_eq!(find("Commodore 64", "这一集只讲 IBM 和苹果"), Found::No);
        assert_eq!(same_title("尾聲：走向1990年代", "第三章：家用电脑"), None);
        assert!(title_similarity("1982：家用電腦的黃金時代", "1982：家用电脑") > 0.4);
    }

    #[test]
    fn detects_traditional_in_simplified_script() {
        assert_eq!(traditional_chars("序章：個人電腦革命之前"), vec!['個', '腦', '電']);
        assert!(traditional_chars("序章：个人电脑革命之前").is_empty());
        assert!(traditional_chars("乾坤与瞭望").is_empty(), "ambiguous characters are not reported");
    }
}
